{"command":"cat > main.go <<'GOEOF'
package main

import (
	"bytes"
	"crypto/md5"
	"encoding/hex"
	"flag"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"io/fs"
	"log"
	"os"
	"os/user"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"unicode"
)

const versionStr = "3.0.0-20260611193416-a37f51062178"
const versionBuiltWith = "go1.26.0"
const versionTag = "v3.0.0-20260611193416-a37f51062178"
const versionCommit = "n/a"
const versionSource = "github.com/incu6us/goimports-reviser/v3"

// std packages set - populated in init from embedded list
var stdPkgs map[string]bool

func main() {
	log.SetFlags(log.Ldate | log.Ltime)
	// Define flags with exact usage strings
	var (
		applyToGenerated = flag.Bool("apply-to-generated-files", false, "Apply imports sorting and formatting(if the option is set) to generated files. Generated file is a file with first comment which starts with comment '// Code generated'. Optional parameter.")
		companyPrefixes  = flag.String("company-prefixes", "", "Company package prefixes which will be placed after 3rd-party group by default(if defined). Values should be comma-separated. Optional parameters.")
		excludes         = flag.String("excludes", "", "Exclude files or dirs, example: '.git/,proto/*.go'.")
		filePath         = flag.String("file-path", "", "Deprecated. Put file name as an argument(last item) of command line.")
		doFormat         = flag.Bool("format", false, "Option will perform additional formatting. Optional parameter.")
		importsOrder     = flag.String("imports-order", "std,general,company,project", "Your imports groups can be sorted in your way. \n    \tstd - std import group; \n    \tgeneral - libs for general purpose; \n    \tcompany - inter-org or your company libs(if you set '-company-prefixes'-option, then 4th group will be split separately. In other case, it will be the part of general purpose libs); \n    \tproject - your local project dependencies;\n    \tblanked - imports with \"_\" alias;\n    \tdotted - imports with \".\" alias.\n    \tOptional parameter.")
		listDiff      = flag.Bool("list-diff", false, "Option will list files whose formatting differs from goimports-reviser. Optional parameter.")
		local         = flag.String("local", "", "Deprecated")
		output        = flag.String("output", "file", "Can be \"file\", \"write\" or \"stdout\". Whether to write the formatted content back to the file or to stdout. When \"write\" together with \"-list-diff\" will list the file name and write back to the file. Optional parameter.")
		projectName   = flag.String("project-name", "", "Your project name(ex.: github.com/incu6us/goimports-reviser). Optional parameter.")
		recursive     = flag.Bool("recursive", false, "Apply rules recursively if target is a directory. In case of ./... execution will be recursively applied by default. Optional parameter.")
		rmUnused      = flag.Bool("rm-unused", false, "Remove unused imports. Optional parameter.")
		separateNamed = flag.Bool("separate-named", false, "Option will separate named imports from the rest of the imports, per group. Optional parameter.")
		setAlias      = flag.Bool("set-alias", false, "Set alias for versioned package names, like 'github.com/go-pg/pg/v9'. In this case import will be set as 'pg \"github.com/go-pg/pg/v9\"'. Optional parameter.")
		setExitStatus = flag.Bool("set-exit-status", false, "set the exit status to 1 if a change is needed/made. Optional parameter.")
		useCache      = flag.Bool("use-cache", false, "Use cache to improve performance. Optional parameter.")
		version       = flag.Bool("version", false, "Show version information")
		versionOnly   = flag.Bool("version-only", false, "Show only the version string")
	)
	flag.Parse()

	// Handle version flags (version-only takes precedence if both? original prints version-only when both set)
	if *versionOnly {
		fmt.Println(versionStr)
		os.Exit(0)
	}
	if *version {
		fmt.Printf("version: %s\n", versionStr)
		fmt.Printf("built with: %s\n", versionBuiltWith)
		fmt.Printf("tag: %s\n", versionTag)
		fmt.Printf("commit: %s\n", versionCommit)
		fmt.Printf("source: %s\n", versionSource)
		os.Exit(0)
	}

	// Validate imports-order
	orderList, orderErr := parseImportsOrder(*importsOrder)
	if orderErr != "" {
		flag.Usage()
		if strings.HasPrefix(orderErr, "unknown") {
			log.Fatalf("unknown order group type: %q", orderErr[len("unknown:"):])
		} else {
			log.Fatalf("use default at least 4 parameters to sort groups of your imports: \"std,general,company,project\"")
		}
	}

	// Validate output
	if *output != "file" && *output != "write" && *output != "stdout" {
		// Need to log Paths and Processing first? Original logs Paths/Processing before invalid output error.
		// For invalid output, it still logs Paths and Processing for the file, then error.
		// So we need to handle paths first, then validate output per file? Or validate after logging?
		// Actually original logs Paths/Processing even for invalid output, then fails.
		// We'll handle this in processing loop.
	}

	// Collect paths
	args := flag.Args()
	paths := append([]string{}, args...)
	if *filePath != "" {
		paths = append(paths, *filePath)
	}
	if len(paths) == 0 {
		flag.Usage()
		log.Fatalf("no file(s) or directory(ies) specified on input")
	}

	log.Printf("Paths: %v", paths)

	// Parse company prefixes
	companyList, companyEnabled := parseCompanyPrefixes(*companyPrefixes)

	// Parse excludes
	excludeList := parseExcludes(*excludes)

	cfg := &Config{
		ApplyToGenerated: *applyToGenerated,
		CompanyPrefixes:  companyList,
		CompanyEnabled:   companyEnabled,
		Excludes:         excludeList,
		DoFormat:         *doFormat,
		Order:            orderList,
		RawOrder:         *importsOrder,
		ListDiff:         *listDiff,
		Output:           *output,
		ProjectName:      *projectName,
		Recursive:        *recursive,
		RmUnused:         *rmUnused,
		SeparateNamed:    *separateNamed,
		SetAlias:         *setAlias,
		SetExitStatus:    *setExitStatus,
		UseCache:         *useCache,
		FilePathSet:      *filePath != "",
		LocalSet:         *local != "",
	}

	// Process each path sequentially, abort on first error
	needExit1 := false // for set-exit-status with files (not directories)
	for _, p := range paths {
		log.Printf("Processing %s", p)
		// Validate output per path (to match logging order: Paths/Processing before invalid output error)
		if cfg.Output != "file" && cfg.Output != "write" && cfg.Output != "stdout" {
			log.Fatalf("invalid output %q specified", cfg.Output)
		}
		isDir, isFile, statErr := checkPath(p)
		_ = isFile
		if statErr != nil {
			// Path doesn't exist or other error -> Failed to fix file: open ...
			abs, _ := filepath.Abs(p)
			// Original error is "open /abs/path: no such file or directory" (from os.Open)
			// Use same message
			log.Fatalf("Failed to fix file: open %s: no such file or directory", abs)
		}
		if p == "./..." {
			// Special recursive from CWD
			project, projErr := determineProjectForDir(".", cfg.ProjectName)
			if projErr != "" {
				flag.Usage()
				log.Fatalf("Could not determine project name for path %s: %s", p, projErr)
			}
			files, walkErr := collectFilesForDotDotDot(".", cfg.Recursive, true, excludeList)
			if walkErr != "" {
				log.Fatalf("Failed to fix directory %s: failed to walk dif: %s", p, walkErr)
			}
			// For directory, set-exit-status is ignored (always 0) unless list-diff?
			// Actually for directory without list-diff, set-exit-status ignored.
			// For directory with list-diff + set-exit-status, exit 1 if any diff.
			// Handle below.
			dirChanged, dirErr := processDirectoryFiles(files, project, cfg)
			if dirErr != "" {
				log.Fatalf("Failed to fix directory %s: failed to walk dif: %s", p, dirErr)
			}
			if cfg.ListDiff && cfg.SetExitStatus && dirChanged {
				needExit1 = true
			}
			// For directory without list-diff, set-exit-status ignored (no exit1 even if changed)
			continue
		}
		if isDir {
			// Directory path
			project, projErr := determineProjectForDir(p, cfg.ProjectName)
			if projErr != "" {
				flag.Usage()
				log.Fatalf("Could not determine project name for path %s: %s", p, projErr)
			}
			files, walkErr := collectFilesForDir(p, cfg.Recursive, excludeList)
			if walkErr != "" {
				log.Fatalf("Failed to fix directory %s: failed to walk dif: %s", p, walkErr)
			}
			dirChanged, dirErr := processDirectoryFiles(files, project, cfg)
			if dirErr != "" {
				log.Fatalf("Failed to fix directory %s: failed to walk dif: %s", p, dirErr)
			}
			if cfg.ListDiff && cfg.SetExitStatus && dirChanged {
				needExit1 = true
			}
			continue
		}
		// File path
		changed, errMsg := processSingleFile(p, cfg)
		if errMsg != "" {
			// errMsg already includes prefix? For file errors, prefix is "Failed to fix file: ..."
			// But for some errors (like project determination), need Usage + different prefix.
			// processSingleFile returns full message after "Failed to fix file: "? Or full?
			// We'll handle: if errMsg starts with "PROJECT:", then do Usage + Could not determine...
			if strings.HasPrefix(errMsg, "PROJECT:") {
				flag.Usage()
				log.Fatalf("Could not determine project name for path %s: %s", p, errMsg[len("PROJECT:"):])
			} else if strings.HasPrefix(errMsg, "WRITE:") {
				log.Fatalf("%s", errMsg[len("WRITE:"):])
			} else if strings.HasPrefix(errMsg, "PACKAGE_ERRORS:") {
				// Package errors already printed to stderr (without log prefix)? Original prints them directly to stderr (not via log).
				// They are printed as "main.go:5:2: ..." lines to stderr, then log.Fatalf for Failed to fix file.
				// processSingleFile already printed them, now log fatal
				log.Fatalf("Failed to fix file: package has an errors")
			} else {
				log.Fatalf("Failed to fix file: %s", errMsg)
			}
		}
		if changed && cfg.SetExitStatus {
			needExit1 = true
		}
	}

	// Handle deprecated flags (after processing, exit 1)
	if cfg.FilePathSet {
		log.Printf("-file-path is deprecated. Put file name(s) as last argument to the command(Example: goimports-reviser -rm-unused -set-alias -format goimports-reviser/main.go)")
		log.Printf("All changes to file are applied, but command-line syntax should be fixed")
		os.Exit(1)
	}
	if cfg.LocalSet {
		log.Printf("-local is deprecated and will be removed soon. Use -company-prefixes instead.")
		log.Printf("All changes to file are applied, but command-line syntax should be fixed")
		os.Exit(1)
	}

	if needExit1 {
		os.Exit(1)
	}
	os.Exit(0)
}

type Config struct {
	ApplyToGenerated bool
	CompanyPrefixes  []string
	CompanyEnabled   bool
	Excludes         []string
	DoFormat         bool
	Order            []string
	RawOrder         string
	ListDiff         bool
	Output           string
	ProjectName      string
	Recursive        bool
	RmUnused         bool
	SeparateNamed    bool
	SetAlias         bool
	SetExitStatus    bool
	UseCache         bool
	FilePathSet      bool
	LocalSet         bool
}

func parseImportsOrder(s string) ([]string, string) {
	if s == "" {
		return []string{"std", "general", "company", "project"}, ""
	}
	parts := strings.Split(s, ",")
	var order []string
	for _, p := range parts {
		t := strings.TrimSpace(p)
		// Check valid
		if t != "std" && t != "general" && t != "company" && t != "project" && t != "blanked" && t != "dotted" {
			return nil, "unknown:" + t
		}
		order = append(order, t)
	}
	// Must contain at least std,general,company,project
	has := map[string]bool{}
	for _, o := range order {
		has[o] = true
	}
	if !(has["std"] && has["general"] && has["company"] && has["project"]) {
		return nil, "missing"
	}
	return order, ""
}

func parseCompanyPrefixes(s string) ([]string, bool) {
	if s == "" {
		return nil, false
	}
	// Split by comma, trim spaces. If any empty after trim, disable.
	parts := strings.Split(s, ",")
	var list []string
	for _, p := range parts {
		t := strings.TrimSpace(p)
		if t == "" {
			return nil, false
		}
		list = append(list, t)
	}
	if len(list) == 0 {
		return nil, false
	}
	return list, true
}

func parseExcludes(s string) []string {
	if s == "" {
		return nil
	}
	parts := strings.Split(s, ",")
	var list []string
	for _, p := range parts {
		t := strings.TrimSpace(p)
		if t == "" {
			continue
		}
		// Strip leading ./ ?
		// Original handles ./a/b.go same as a/b.go, so normalize by stripping leading ./
		for strings.HasPrefix(t, "./") {
			t = t[2:]
		}
		list = append(list, t)
	}
	return list
}

func checkPath(p string) (isDir bool, isFile bool, err error) {
	// Special case ./... is considered dir (handled separately)
	if p == "./..." {
		return true, false, nil
	}
	fi, e := os.Stat(p)
	if e != nil {
		return false, false, e
	}
	if fi.IsDir() {
		return true, false, nil
	}
	return false, true, nil
}

