package main

import (
	"crypto/md5"
	"encoding/hex"
	"os"
	"os/user"
	"path/filepath"
)

func getCacheDir() string {
	// Original uses user.Current().HomeDir + "/.cache/goimports-reviser" (ignores env)
	if u, err := user.Current(); err == nil && u.HomeDir != "" {
		return filepath.Join(u.HomeDir, ".cache", "goimports-reviser")
	}
	// Fallback to os.UserHomeDir?
	if h, err := os.UserHomeDir(); err == nil && h != "" {
		return filepath.Join(h, ".cache", "goimports-reviser")
	}
	return ""
}

func getCacheKey(absPath string) string {
	h := md5.Sum([]byte(absPath))
	return hex.EncodeToString(h[:])
}

func getFileHash(content []byte) string {
	h := md5.Sum(content)
	return hex.EncodeToString(h[:])
}

func checkCache(absPath string, currentContent []byte) bool {
	// Returns true if cache hit (current hash == cached hash), meaning skip processing
	dir := getCacheDir()
	if dir == "" {
		return false
	}
	key := getCacheKey(absPath)
	cacheFile := filepath.Join(dir, key)
	cached, err := os.ReadFile(cacheFile)
	if err != nil {
		return false
	}
	cachedStr := string(cached)
	// Cached file contains 32 hex chars, possibly without newline? Original contains exactly 32 chars, no newline.
	cachedStr = trimSpace(cachedStr)
	current := getFileHash(currentContent)
	return cachedStr == current
}

func updateCache(absPath string, formattedContent []byte) {
	dir := getCacheDir()
	if dir == "" {
		return
	}
	os.MkdirAll(dir, 0755)
	key := getCacheKey(absPath)
	cacheFile := filepath.Join(dir, key)
	hash := getFileHash(formattedContent)
	os.WriteFile(cacheFile, []byte(hash), 0644)
}

